grm(){return"\u0cab\u0cc7\u0cb8\u0ccd \u0cb5\u0cc6\u0cb0\u0cbf\u0cab\u0cbf\u0c95\u0cc7\u0cb6\u0ca8\u0ccd \u0cb5\u0cbf\u0cab\u0cb2\u0cb5\u0cbe\u0c97\u0cbf\u0ca6\u0cc6. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
gru(){return"\u0cae\u0cc1\u0c82\u0ca6\u0cc1\u0cb5\u0cb0\u0cbf\u0caf\u0cb2\u0cc1 \u0cb2\u0cca\u0c95\u0cc7\u0cb6\u0ca8\u0ccd \u0caa\u0cb0\u0ccd\u0cae\u0cbf\u0cb7\u0ca8\u0ccd \u0c85\u0c97\u0ca4\u0ccd\u0caf."},
